import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFlow Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFlow/aireflow-v2-40-0.md","filePath":"aireblock-releases/AireFlow/aireflow-v2-40-0.md","lastUpdated":1787059744000}`),a={name:`aireblock-releases/AireFlow/aireflow-v2-40-0.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireflow-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireflow-icon.png"> AireFlow Release Notes</span> <a class="header-anchor" href="#aireflow-release-notes" aria-label="Permalink to “AireFlow Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 2.40.0<br><strong>Release Date:</strong> 26 August 2026</p></blockquote><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to “Summary of Changes”">​</a></h2><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Instant Liquid Expression Preview (FLOW-1285)</li><li>Monorepo-Friendly AireFlow Folder Structure (FLOW-1330)</li><li>Delete Individual Workflow Versions (FLOW-1332)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Fixed GraphQL Errors for Historic Tasks Without a Task Key (FLOW-1338)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="instant-liquid-expression-preview-flow-1285" tabindex="-1">Instant Liquid Expression Preview (FLOW-1285) <a class="header-anchor" href="#instant-liquid-expression-preview-flow-1285" aria-label="Permalink to “Instant Liquid Expression Preview (FLOW-1285)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Liquid expressions used in HTTP Request Body fields and mutations can now be evaluated instantly using the task&#39;s input context, giving you a live preview of the rendered result as you write your expression.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can see exactly what your Liquid expressions will produce before running the workflow, making it much quicker to write and check HTTP request bodies and mutations.</p></div><h4 id="monorepo-friendly-aireflow-folder-structure-flow-1330" tabindex="-1">Monorepo-Friendly AireFlow Folder Structure (FLOW-1330) <a class="header-anchor" href="#monorepo-friendly-aireflow-folder-structure-flow-1330" aria-label="Permalink to “Monorepo-Friendly AireFlow Folder Structure (FLOW-1330)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>AireFlow definitions (workflows, event definition groups, and transition sets) can now optionally be organised inside an &quot;AireFlow&quot; folder within your repository, aligning with the improved structure already used by AireGlu. This is fully backwards compatible — repositories using the existing flat structure will continue to work without any changes.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>If you keep AireFlow configuration alongside other products in the same repository, you can now group everything under a dedicated AireFlow folder for a tidier, monorepo-friendly layout, without breaking any existing setup.</p></div><h4 id="delete-individual-workflow-versions-flow-1332" tabindex="-1">Delete Individual Workflow Versions (FLOW-1332) <a class="header-anchor" href="#delete-individual-workflow-versions-flow-1332" aria-label="Permalink to “Delete Individual Workflow Versions (FLOW-1332)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>You can now delete individual workflow versions rather than only being able to delete an entire workflow. Deleting a version does not renumber the remaining versions, so deleting v1 from a workflow with versions 1 to 4 leaves versions 2, 3, and 4 intact.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>If you accidentally create an unwanted workflow version, you can now remove just that version instead of being stuck with it, or having to delete the whole workflow.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="fixed-graphql-errors-for-historic-tasks-without-a-task-key-flow-1338" tabindex="-1">Fixed GraphQL Errors for Historic Tasks Without a Task Key (FLOW-1338) <a class="header-anchor" href="#fixed-graphql-errors-for-historic-tasks-without-a-task-key-flow-1338" aria-label="Permalink to “Fixed GraphQL Errors for Historic Tasks Without a Task Key (FLOW-1338)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed a GraphQL error that occurred when fetching a task that predates the introduction of task keys in late 2022. Historic tasks without a task key now correctly return null for that field instead of causing the query to fail, while task keys remain required for newly created tasks.</p></div>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};